            QuizItem("ما التسبيح المشروع بعد الصلوات المكتوبات؟", listOf("ثلاث وثلاثون تسبيحة وتحميد وتكبير", "سبع عشرة", "عشر عشرة", "لا يسن"), 0, "33 تسبيحة و33 تحميدة و33 تكبيرة وتمام المئة لا إله إلا الله وحده لا شريك له."),
            QuizItem("بم يصلي المسلم على النبي ﷺ بعد الأذان؟", listOf("اللهم رب هذه الدعوة التامة...", "لا إله إلا الله", "الحمد لله", "سبحان الله"), 0, "من صلى عليه حين يسمع النداء حلت له الشفاعة يوم القيامة."),
            QuizItem("ما السورتان اللتان قرأهما النبي ﷺ قبل النوم على سنة دائمة؟", listOf("الملك والسجدة", "الكهف", "يس", "الرحمن"), 0, "كان ﷺ ينام على قراءتهما كل ليلة."),
